// NOTE: Assertions have been autogenerated by utils/update_cc_test_checks.py UTC_ARGS: --version 6
// RUN: %clang_cc1 -triple x86_64-unknown-linux-gnu -fcxx-exceptions -fexceptions -emit-llvm -o - %s | FileCheck %s

// __atomic_is_lock_free does not throw, like the other functions of the atomic
// library, so calling it needs no landing pad, not even in a function that
// must not let an exception through.

// CHECK-LABEL: define dso_local noundef zeroext i1 @_Z9lock_freePv(
// CHECK-SAME: ptr noundef [[P:%.*]]) #[[ATTR0:[0-9]+]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[P_ADDR:%.*]] = alloca ptr, align 8
// CHECK-NEXT:    store ptr [[P]], ptr [[P_ADDR]], align 8
// CHECK-NEXT:    [[TMP0:%.*]] = load ptr, ptr [[P_ADDR]], align 8
// CHECK-NEXT:    [[CALL:%.*]] = call noundef zeroext i1 @__atomic_is_lock_free(i64 noundef 16, ptr noundef [[TMP0]])
// CHECK-NEXT:    ret i1 [[CALL]]
//
bool lock_free(void *p) noexcept {
  return __atomic_is_lock_free(16, p);
}

// CHECK-LABEL: define dso_local noundef zeroext i1 @_Z13c11_lock_freev(
// CHECK-SAME: ) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[CALL:%.*]] = call noundef zeroext i1 @__atomic_is_lock_free(i64 noundef 16, ptr noundef null)
// CHECK-NEXT:    ret i1 [[CALL]]
//
bool c11_lock_free() noexcept {
  return __c11_atomic_is_lock_free(16);
}
